package net.officefloor.hq.app.person;

/** The person just named as a patron. */
public record Patron(Person person) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Names another person on the sheet as the person's patron: not themselves, and not twice. */
public class AddPatron {
    public void add(@Val PatronInput input, @Val Sheet sheet, @Val Person person,
            PersonRepository repository, Out<Patron> patronOut) throws InvalidPersonException {
        Person patron = repository.find(sheet.id(), input.patronId());
        if (patron == null) throw new InvalidPersonException("No such patron");
        if (patron.getId().equals(person.getId())) throw new InvalidPersonException("A person cannot be their own patron");
        if (person.getPatronIds().contains(patron.getId())) throw new InvalidPersonException("Already a patron");
        repository.addPatron(person, patron);
        patronOut.set(new Patron(patron));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/**
 * A person, as the screen reads it (their grade the one in force on the sheet's today), with their statement count, and the last statement's due-total
 * and date ("" before the first), whether they are retired and the date they are retired from
 * ("" when not), whether they have any hold, their holds (in the order added), the ids of the people they name as patrons, and every
 * grade they have been given with the date it is from (the first "", from the beginning of time),
 * by from-date, their own terms in days ("" for none), their contact ("" for none), and their aliases
 * (in the order given).
 */
public record PersonResponse(String id, String name, String grade, long version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<HoldFrom> holds, java.util.List<String> patronIds, List<GradeFrom> grades, String terms,
        String contact, List<String> aliases) {

    /** A hold from a date to a date (yyyy-MM-dd; to "" when open-ended), both inclusive. */
    public record HoldFrom(String from, String to) {}

    /** A grade in force from a date (yyyy-MM-dd; "" from the beginning of time). */
    public record GradeFrom(String from, String grade) {}

    /** The person as the screen reads it on the sheet's today: their grade is the one in force on it. */
    public static PersonResponse from(Person person, LocalDate today) {
        List<GradeFrom> grades = new ArrayList<>();
        grades.add(new GradeFrom("", person.getGrade()));
        person.getDatedGrades().forEach((from, grade) -> grades.add(new GradeFrom(from.toString(), grade)));
        return new PersonResponse(String.valueOf(person.getId()), person.getName(), person.gradeOn(today),
                person.getVersion(), person.getStatementCount(),
                person.getStatedTotal() == null ? "" : person.getStatedTotal(),
                person.getStatementDate() == null ? "" : person.getStatementDate().toString(),
                person.isRetired(), person.getRetiredFrom() == null ? "" : person.getRetiredFrom().toString(),
                person.isHeld(),
                person.getHolds().stream().map((h) -> new HoldFrom(h.from().toString(), h.to() == null ? "" : h.to().toString())).toList(),
                person.getPatronIds().stream().map(String::valueOf).toList(), grades,
                person.getTerms() == null ? "" : person.getTerms().toString(),
                person.getContact() == null ? "" : person.getContact(), List.copyOf(person.getAliases()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** A person on a sheet, as the store holds it. {@code id} is null until first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    private String grade;
    private Integer terms;
    private String contact;
    private long version;
    private int statementCount;
    private String statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    private LocalDate addedOn;
    private final List<Hold> holds = new ArrayList<>();
    private final List<Long> patronIds = new ArrayList<>();
    private final List<String> aliases = new ArrayList<>();
    private final TreeMap<LocalDate, String> datedGrades = new TreeMap<>();

    public Person(Long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(Long id, String sheetId, String name, String grade, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
        this.version = version;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    /** The first grade they were given: in force from the beginning of time, until their first dated grade. */
    public String getGrade() { return grade; }
    public void setGrade(String grade) { this.grade = grade; }
    /** Their own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    public Integer getTerms() { return terms; }
    public void setTerms(Integer terms) { this.terms = terms; }
    /** Their contact, trimmed and lower-cased; null when they have none. */
    public String getContact() { return contact; }
    public void setContact(String contact) { this.contact = contact; }
    /** The grades recorded from a date, by from-date: each in force from it until the next. */
    public Map<LocalDate, String> getDatedGrades() { return datedGrades; }
    /** Record the grade from this date, replacing any recorded from the same date. */
    public void setGradeFrom(String grade, LocalDate from) { datedGrades.put(from, grade); }
    /** The grade in force on the date: the latest dated one on or before it, else the first grade. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> dated = datedGrades.floorEntry(date);
        return dated == null ? grade : dated.getValue();
    }
    /** Raised by one on each save; an edit names the version it was made from. */
    public long getVersion() { return version; }
    public void setVersion(long version) { this.version = version; }
    /** How many statements have been taken for them. */
    public int getStatementCount() { return statementCount; }
    /** The last statement's due-total (n/a when it had none); null before the first. */
    public String getStatedTotal() { return statedTotal; }
    /** The sheet's today when the last statement was taken; null before the first. */
    public LocalDate getStatementDate() { return statementDate; }
    public void setStatements(int count, String statedTotal, LocalDate statementDate) {
        this.statementCount = count;
        this.statedTotal = statedTotal;
        this.statementDate = statementDate;
    }
    /** The sheet's today when they were added; null when it was not kept (from the beginning of time). */
    public LocalDate getAddedOn() { return addedOn; }
    public void setAddedOn(LocalDate addedOn) { this.addedOn = addedOn; }
    /** Whether they had been added by the end of {@code day}. */
    public boolean addedBy(LocalDate day) { return addedOn == null || !addedOn.isAfter(day); }
    /** The date they are retired from; null when not retired. Set at all, they count as retired. */
    public LocalDate getRetiredFrom() { return retiredFrom; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    public boolean isRetired() { return retiredFrom != null; }
    /** Their holds, in the order added: each from a date to an optional to-date. */
    public List<Hold> getHolds() { return holds; }
    /** Whether they have any hold at all. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** Whether the date is within one of their holds: an OPEN claim on it, not bound by a statement, counts in no total. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch((h) -> h.covers(date)); }
    /** Whether their retirement date is reached on {@code today}: retired from it or an earlier date. */
    public boolean retiredOn(LocalDate today) { return retiredFrom != null && today != null && !today.isBefore(retiredFrom); }
    /**
     * Whether an OPEN or PENDING claim of theirs on the date, not bound by a statement, counts in no
     * total on {@code today}: the date is within one of their holds, or their retirement date is reached.
     */
    public boolean heldOn(LocalDate date, LocalDate today) { return heldOn(date) || retiredOn(today); }
    /** The ids of the people they name as patrons, in the order named. */
    public List<Long> getPatronIds() { return patronIds; }
    /** Their aliases, trimmed, in the order given: like names, none equal (ignoring case) any name or alias on the sheet. */
    public List<String> getAliases() { return aliases; }
    /** Whether a claim on this date is refused: they are retired from an earlier date. */
    public boolean retiredBefore(LocalDate date) { return retiredFrom != null && date.isAfter(retiredFrom); }
}
-- The people a person names as their patrons: other people on the same sheet, each at most once.
CREATE TABLE person_patron (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    person_id BIGINT NOT NULL REFERENCES person(id),
    patron_id BIGINT NOT NULL REFERENCES person(id),
    PRIMARY KEY (person_id, patron_id)
);
CREATE INDEX person_patron_sheet ON person_patron(sheet_id);
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { PersonHead, PersonRow } from '../../slots/defs/personRow';
import { gradeOn, usePeople, peopleKey } from '../people/people';
import type { Person } from '../people/people';
import { useClaims } from '../claims/claims';
import { addDays, claimDue, rateOn, sumDue, useRates } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';
import { useFloor, useLate } from '../access/access';
import { useUser } from '../session/session';

function PatronsHead() {
  return (
    <>
      <th>Patrons</th>
      <th>Backing</th>
      <th />
    </>
  );
}

// A person's patrons (names, sorted), their backing (the patrons' settled figures over their SETTLED
// claims dated within the 90 days up to and including the sheet's today, added up, skipping n/a), and a picker that names one more person on the sheet as a patron.
function PersonPatrons({ sheetId, person }: { sheetId: string; person: Person }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const [choice, setChoice] = useState('');
  const [error, setError] = useState('');
  const once = useOnce();

  const patrons = people.filter((p) => person.patronIds.includes(p.id));
  const names = patrons.map((p) => p.name).sort((a, b) => a.localeCompare(b)).join(', ');
  const since = today === '' ? '' : addDays(today, -89);
  const backing = sumDue(
    patrons.flatMap((p) =>
      claims
        .filter((c) => c.personId === p.id && c.status === 'SETTLED' && c.date >= since && c.date <= today)
        .map((c) => claimDue(c, rateOn(rates, gradeOn(p.grades, c.date), c.date), floor, late, gradeOn(p.grades, c.date))),
    ),
  );

  const add = useMutation({
    mutationFn: (patronId: string) =>
      postJson<Person>(
        `/api/sheets/${encodeURIComponent(sheetId)}/people/${encodeURIComponent(person.id)}/patrons`,
        { patronId },
        user,
      ),
    onSuccess: () => {
      setChoice('');
      return queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('That person could not be named as a patron.'),
  });

  const submit = () => {
    setError('');
    once((done) => add.mutate(choice, { onSettled: done }));
  };

  return (
    <>
      <td data-testid="person-patrons">{names}</td>
      <td data-testid="person-backing">{backing}</td>
      <td>
        <select
          data-testid="person-patron-select"
          value={choice}
          onChange={(e) => {
            setChoice(e.target.value);
            setError('');
          }}
        >
          <option value="">—</option>
          {people.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name}
            </option>
          ))}
        </select>
        <button type="button" data-testid="person-patron-add" onClick={submit} disabled={add.isPending}>
          Add patron
        </button>
        {error && (
          <p role="alert" data-testid="person-patron-error">
            {error}
          </p>
        )}
      </td>
    </>
  );
}

export const contributions = [
  PersonHead.fill({ order: 60, Component: PatronsHead }),
  PersonRow.fill({ order: 60, Component: PersonPatrons }),
];
